package com.tfluid.xdrive.core

import org.junit.Assert.*
import org.junit.Test

/** Public deterministic vector independently generated by WebCrypto/Python.
 * Swift CryptoKit uses the same salt/AAD/nonce/ciphertext byte protocol. */
class XDriveClipboardCryptoTest {
    private val passphrase = "correct horse battery staple 🔐"
    private val salt = "AAECAwQFBgcICQoLDA0ODw=="
    private val owner = "https://drive.example.test:42"
    private val eventID = "4cf139e0-6b1f-4b84-99c9-d82ea712ab25"
    private val nonce = "oKGio6Slpqeoqaqr"
    private val cipher = "DBpmpmEsZYMMJ9WiQxI6BMJDOKRQQPCZYQQbiuxUSi85OYUKQxXJdji3cu9Vx65Y1xKAkxfqdXA="
    private val text = "跨平台 Clipboard ✓\nsecond line 🚀"

    @Test fun webAndAndroidDecodeExactlySameEncryptedBytes() {
        val key = XDriveClipboardCrypto.deriveKey(passphrase,salt)
        assertEquals("d77ace3bdbdd6a6faa0ac651e2e2b9b21559cb8d904e1155b697077656a4647a",
            key.encoded.joinToString("") { "%02x".format(it.toInt() and 0xff) })
        val wire = XDriveClipboardCrypto.Wire(eventID,"text/plain",nonce,cipher)
        assertEquals(text,XDriveClipboardCrypto.decrypt(wire,key,owner))
        assertThrows(Exception::class.java) {
            XDriveClipboardCrypto.decrypt(wire,key,owner+":wrong")
        }
        assertThrows(Exception::class.java) {
            XDriveClipboardCrypto.decrypt(wire.copy(kind="text/uri-list"),key,owner)
        }
        assertThrows(Exception::class.java) {
            XDriveClipboardCrypto.decrypt(wire.copy(nonce="AA=="),key,owner)
        }
    }
    @Test fun newMessagesHaveUniqueNoncesAndAuthenticateEventIdentity() {
        val key = XDriveClipboardCrypto.deriveKey(passphrase,salt)
        val a = XDriveClipboardCrypto.encrypt(text,key,owner)
        val b = XDriveClipboardCrypto.encrypt(text,key,owner)
        assertNotEquals(a.clientEventID,b.clientEventID)
        assertNotEquals(a.nonce,b.nonce)
        assertEquals(text,XDriveClipboardCrypto.decrypt(a,key,owner))
        assertThrows(Exception::class.java) {
            XDriveClipboardCrypto.decrypt(a.copy(clientEventID=b.clientEventID),key,owner)
        }
        assertEquals("text/uri-list",XDriveClipboardCrypto.mediaKind("https://example.test/路径"))
        assertEquals("text/plain",XDriveClipboardCrypto.mediaKind("not a URL"))
    }
}
